import { useQueryClient } from "@tanstack/react-query";
import { useActionMutation, useActionQuery } from "../use-action.js";
function recurringParams(scope) {
    return { scope: scope === "org" ? "organization" : "personal" };
}
function automationParams(scope) {
    return { scope: scope === "org" ? "organization" : "personal" };
}
/**
 * Deploy-scoped and fixed for the life of the process, so it is cached far
 * longer than the automation lists.
 */
export function useScheduledTriggerState() {
    const query = useActionQuery("get-scheduled-trigger-status", {}, { staleTime: 5 * 60_000 });
    // Data first: a cached answer with a failing background refetch is still an
    // answer, and downgrading it to `unknown` would flicker the warning off.
    if (query.data)
        return { kind: "resolved", status: query.data };
    if (query.error)
        return { kind: "unknown", error: query.error };
    return { kind: "loading" };
}
export function useRecurringJobs(scope) {
    return useActionQuery("list-recurring-jobs", recurringParams(scope), { staleTime: 5_000 });
}
export function useAutomations(scope) {
    return useActionQuery("list-automations", automationParams(scope), { staleTime: 5_000 });
}
export function useManageRecurringJob(scope) {
    const queryClient = useQueryClient();
    const params = recurringParams(scope);
    const queryKey = ["action", "list-recurring-jobs", params];
    return useActionMutation("manage-recurring-job", {
        onMutate: async (variables) => {
            await queryClient.cancelQueries({ queryKey });
            const previous = queryClient.getQueryData(queryKey);
            queryClient.setQueryData(queryKey, (current) => {
                if (!current)
                    return current;
                if (variables.operation === "delete") {
                    return current.filter((job) => job.name !== variables.name);
                }
                return current.map((job) => job.name === variables.name
                    ? { ...job, ...optimisticPatch(variables) }
                    : job);
            });
            return { previous };
        },
        onError: (_error, _variables, context) => {
            const rollback = context;
            if (rollback && "previous" in rollback) {
                queryClient.setQueryData(queryKey, rollback.previous);
            }
        },
    });
}
export function useManageAutomation(scope) {
    const queryClient = useQueryClient();
    const params = automationParams(scope);
    const queryKey = ["action", "list-automations", params];
    return useActionMutation("manage-automation", {
        onMutate: async (variables) => {
            await queryClient.cancelQueries({ queryKey });
            const previous = queryClient.getQueryData(queryKey);
            queryClient.setQueryData(queryKey, (current) => {
                if (!current)
                    return current;
                if (variables.operation === "delete") {
                    return current.filter((automation) => automation.name !== variables.name);
                }
                return current.map((automation) => automation.name === variables.name
                    ? { ...automation, ...optimisticPatch(variables) }
                    : automation);
            });
            return { previous };
        },
        onError: (_error, _variables, context) => {
            const rollback = context;
            if (rollback && "previous" in rollback) {
                queryClient.setQueryData(queryKey, rollback.previous);
            }
        },
    });
}
export function useRunAutomationNow() {
    const queryClient = useQueryClient();
    return useActionMutation("run-automation-now", {
        onSuccess: (_result, variables) => {
            const scope = variables.scope === "organization" ? "organization" : "personal";
            const name = variables.name ??
                variables.path?.replace(/^jobs\//, "").replace(/\.md$/, "");
            void queryClient.invalidateQueries({
                queryKey: ["action", "list-automation-runs", { scope, name }],
            });
            void queryClient.invalidateQueries({
                queryKey: ["action", "list-automations", { scope }],
            });
            void queryClient.invalidateQueries({
                queryKey: ["action", "list-recurring-jobs", { scope }],
            });
        },
    });
}
function optimisticPatch(variables) {
    const patch = {};
    if (variables.enabled !== undefined)
        patch.enabled = variables.enabled;
    if (variables.schedule !== undefined)
        patch.schedule = variables.schedule;
    if (variables.timezone !== undefined)
        patch.timezone = variables.timezone;
    return patch;
}
export function useAutomationRuns(scope, name, active) {
    const params = {
        scope: scope === "org" ? "organization" : "personal",
        name: name || "",
    };
    return useActionQuery("list-automation-runs", params, {
        staleTime: 5_000,
        enabled: active && Boolean(name),
    });
}
